<?php
defined('ABSPATH')||exit; class CFP_Elementor{public function hooks():void{add_action('elementor/widgets/register',array($this,'widgets')); add_action('elementor/elements/categories_registered',array($this,'category'));} public function category($manager):void{$manager->add_category('conversionflow-pro',array('title'=>__('ConversionFlow Pro','conversionflow-pro'),'icon'=>'fa fa-plug'));} public function widgets($widgets_manager):void{require_once CFP_PATH.'integrations/widgets/class-elementor-widget.php'; foreach(CFP_Elementor_Widget::definitions() as $id=>$label){$widgets_manager->register(new CFP_Elementor_Widget($id,$label));}}}
